import os
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
from pathlib import Path

def main():
    base_dir = Path(__file__).resolve().parent.parent / "results"
    fig_dir = base_dir / "figures"
    fig_dir.mkdir(parents=True, exist_ok=True)
    
    # This script assumes the presence of alpha_grid_summary.csv and other CSVs generated by previous addons
    alpha_csv = base_dir / "alpha_grid_summary.csv"
    ece_csv = base_dir / "ece_calibration_results.csv"
    
    if alpha_csv.exists():
        df_alpha = pd.read_csv(alpha_csv)
        
        # Figure 1: Scaling Law (alpha_theory vs model scale)
        plt.figure(figsize=(8, 6))
        sns.barplot(x="model", y="alpha_theory", data=df_alpha)
        plt.title("Scaling Law of Optimal α")
        plt.ylabel("Theoretical α*")
        plt.xticks(rotation=45)
        plt.tight_layout()
        plt.savefig(fig_dir / "fig1_scaling_law.png")
        plt.close()
        print("Generated fig1_scaling_law.png")
        
    if ece_csv.exists():
        df_ece = pd.read_csv(ece_csv)
        
        # Figure 3: ECE Calibration Bars
        df_melt = df_ece.melt(id_vars="model", value_vars=["ece_raw", "ece_scaled"], var_name="Type", value_name="ECE")
        plt.figure(figsize=(8, 6))
        sns.barplot(x="model", y="ECE", hue="Type", data=df_melt)
        plt.title("Expected Calibration Error (Before/After Temp Scaling)")
        plt.xticks(rotation=45)
        plt.tight_layout()
        plt.savefig(fig_dir / "fig3_ece_bars.png")
        plt.close()
        print("Generated fig3_ece_bars.png")
        
    # Dummy creation for the rest of the 8 figures to ensure the pipeline exists
    for i in [2, 4, 5, 6, 7, 8]:
        fig_path = fig_dir / f"fig{i}_placeholder.png"
        plt.figure()
        plt.text(0.5, 0.5, f"Figure {i} Placeholder", ha='center', va='center')
        plt.savefig(fig_path)
        plt.close()

if __name__ == "__main__":
    main()
